function roundedRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function fitCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(!rect.width||!rect.height)return null;if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {ctx,w:rect.width,h:rect.height}}
function drawFighter(ctx,x,ground,scale,fighter,color,facing=1,pose='idle',time=0){
  ctx.save();ctx.translate(x,ground);ctx.scale(scale*facing,scale);
  const c=color||fighter.color, dark='#14151b', accent=fighter.accent||'#eee';
  let bob=Math.sin(time*5)*1.5, lean=pose==='attack'?-8:pose==='hit'?8:pose==='walk'?Math.sin(time*11)*3:0;
  ctx.translate(lean,bob);
  // grounded shadow
  ctx.fillStyle='#08090c8c';ctx.beginPath();ctx.ellipse(0,1,29,6,0,0,Math.PI*2);ctx.fill();
  const limb=(points,width,stroke)=>{ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=dark;ctx.lineWidth=width+4;ctx.stroke();ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()};
  const walk=pose==='walk'?Math.sin(time*11)*11:0;
  // legs, armored boots
  limb([[-8,-55],[-11+walk*.35,-30],[-15+walk,-5]],16,dark);
  limb([[8,-55],[12-walk*.35,-29],[15-walk,-5]],16,c);
  ctx.fillStyle='#111218';roundedRect(ctx,-27+walk,-9,24,10,3);ctx.fill();ctx.fillStyle=c;roundedRect(ctx,-26+walk,-10,19,4,2);ctx.fill();
  ctx.fillStyle='#111218';roundedRect(ctx,5-walk,-9,24,10,3);ctx.fill();ctx.fillStyle=accent;roundedRect(ctx,7-walk,-10,15,4,2);ctx.fill();
  // belt + torso silhouette
  ctx.fillStyle=dark;ctx.beginPath();ctx.moveTo(-14,-119);ctx.lineTo(13,-119);ctx.lineTo(21,-61);ctx.lineTo(12,-52);ctx.lineTo(-14,-54);ctx.lineTo(-21,-63);ctx.closePath();ctx.fill();
  ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-12,-116);ctx.lineTo(11,-116);ctx.lineTo(16,-67);ctx.lineTo(9,-59);ctx.lineTo(-11,-60);ctx.lineTo(-17,-67);ctx.closePath();ctx.fill();
  ctx.fillStyle=accent;ctx.beginPath();ctx.moveTo(-2,-112);ctx.lineTo(4,-112);ctx.lineTo(2,-71);ctx.lineTo(-4,-71);ctx.closePath();ctx.fill();
  ctx.fillStyle='#17171c';ctx.fillRect(-15,-66,30,7);ctx.fillStyle=accent;ctx.fillRect(-2,-66,5,6);
  // left arm and right arm; punch/kick attack pose changes lead hand
  let reach=pose==='attack'?35:pose==='block'?17:0, guard=pose==='block';
  limb([[-13,-109],[-25,-94],[-26,-76]],11,c);
  ctx.fillStyle=accent;ctx.beginPath();ctx.arc(-26,-74,7,0,Math.PI*2);ctx.fill();
  if(pose==='kick'){
    limb([[12,-107],[24,-94],[43,-83]],12,c);ctx.fillStyle=accent;ctx.beginPath();ctx.arc(44,-82,8,0,Math.PI*2);ctx.fill();
  }else if(guard){
    limb([[13,-108],[26,-127],[12,-144]],12,c);ctx.fillStyle=accent;ctx.beginPath();ctx.arc(11,-145,8,0,Math.PI*2);ctx.fill();
  }else{
    limb([[13,-108],[24+reach*.35,-100],[27+reach,-96]],12,c);ctx.fillStyle=accent;ctx.beginPath();ctx.arc(28+reach,-95,8,0,Math.PI*2);ctx.fill();
  }
  // neck + head
  ctx.fillStyle='#a97862';roundedRect(ctx,-6,-128,12,16,4);ctx.fill();
  ctx.fillStyle='#d5a58b';ctx.beginPath();ctx.ellipse(0,-143,14,17,0,0,Math.PI*2);ctx.fill();
  // hair / mask styling
  ctx.fillStyle=fighter.hair==='buzz'?'#27232d':c;ctx.beginPath();
  if(fighter.hair==='spike'){ctx.moveTo(-14,-145);ctx.lineTo(-16,-162);ctx.lineTo(-7,-153);ctx.lineTo(-1,-170);ctx.lineTo(4,-154);ctx.lineTo(13,-163);ctx.lineTo(13,-143);ctx.closePath()}
  else if(fighter.hair==='hood'){ctx.moveTo(-17,-137);ctx.lineTo(-15,-160);ctx.quadraticCurveTo(0,-176,16,-158);ctx.lineTo(16,-136);ctx.lineTo(9,-143);ctx.lineTo(-9,-142);ctx.closePath()}
  else if(fighter.hair==='buzz'){ctx.ellipse(0,-151,14,8,0,Math.PI,Math.PI*2);ctx.lineTo(13,-146);ctx.lineTo(-14,-146);ctx.closePath()}
  else{ctx.moveTo(-15,-141);ctx.lineTo(-15,-160);ctx.quadraticCurveTo(0,-174,15,-157);ctx.lineTo(14,-128);ctx.lineTo(8,-137);ctx.lineTo(7,-147);ctx.lineTo(-12,-145);ctx.closePath()}
  ctx.fill();
  // eyes, face mask
  ctx.fillStyle='#272027';ctx.fillRect(-9,-145,7,2);ctx.fillRect(3,-145,7,2);
  if(fighter.hair==='hood'||fighter.name==='VANTA'){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-12,-137);ctx.lineTo(12,-137);ctx.lineTo(9,-128);ctx.lineTo(-8,-128);ctx.closePath();ctx.fill()}
  // shoulder plates, seam marks
  ctx.fillStyle=accent;ctx.beginPath();ctx.moveTo(-20,-111);ctx.lineTo(-11,-116);ctx.lineTo(-9,-107);ctx.lineTo(-17,-101);ctx.closePath();ctx.fill();
  ctx.fillStyle='#ffffff39';ctx.fillRect(-13,-108,2,17);
  if(pose==='attack'||pose==='kick'){ctx.globalAlpha=.38;ctx.strokeStyle=accent;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(20,-106);ctx.lineTo(48,-94);ctx.stroke();ctx.globalAlpha=1}
  ctx.restore();
}
function drawStage(ctx,w,h,stage,time,detail=true){
  const [sky,horizon,glow,accent]=stage.colors;
  const grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,sky);grad.addColorStop(.63,horizon);grad.addColorStop(1,'#111319');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
  const sunX=stage.type==='dojo'?w*.76:w*.72,sunY=h*.32;
  const halo=ctx.createRadialGradient(sunX,sunY,2,sunX,sunY,h*.28);halo.addColorStop(0,glow+'aa');halo.addColorStop(1,glow+'00');ctx.fillStyle=halo;ctx.fillRect(0,0,w,h*.78);
  if(stage.type==='dojo'){
    ctx.fillStyle='#d3c18d';ctx.beginPath();ctx.arc(sunX,sunY,h*.07,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#c4b58b66';ctx.lineWidth=1;for(let i=0;i<6;i++){ctx.beginPath();ctx.moveTo(i*w/5,h*.14);ctx.lineTo(i*w/5,h*.54);ctx.stroke()}
    // bamboo silhouettes
    for(let i=0;i<8;i++){let x=i*w/8;ctx.strokeStyle='#101b1b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x,h*.56);ctx.lineTo(x+Math.sin(i*2)*9,h*.2+(i%3)*8);ctx.stroke();for(let j=0;j<3;j++){ctx.beginPath();ctx.moveTo(x,h*.27+j*34);ctx.lineTo(x+12,h*.24+j*34);ctx.stroke()}}
  }else if(stage.type==='lava'){
    ctx.fillStyle='#211619';ctx.beginPath();ctx.moveTo(0,h*.57);for(let i=0;i<=10;i++)ctx.lineTo(i*w/10,h*(.42+Math.sin(i*4.2)*.08));ctx.lineTo(w,h*.65);ctx.lineTo(0,h*.65);ctx.fill();
    ctx.fillStyle='#ff7135';ctx.globalAlpha=.7;for(let i=0;i<8;i++){let x=(i*137+time*8)%(w+20);ctx.beginPath();ctx.arc(x,h*(.54+Math.sin(i*17)*.025),2+(i%3),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
  }else{
    // layered skyline
    for(let layer=0;layer<3;layer++){let base=h*(.59+layer*.025),bw=w/(10+layer*2);for(let x=-bw;x<w+bw;x+=bw){let seed=Math.abs(Math.sin(x*13.7+layer*31));let bh=h*(.14+seed*.26);ctx.fillStyle=layer===0?'#171925':layer===1?'#20202d':'#292232';ctx.fillRect(x,base-bh,bw-2,bh);if(stage.type==='neon'&&layer>0){for(let wy=base-bh+8;wy<base-9;wy+=12){ctx.fillStyle=(Math.floor(wy+x)%3===0?glow:accent);ctx.globalAlpha=.14+seed*.2;for(let wx=x+6;wx<x+bw-5;wx+=10)ctx.fillRect(wx,wy,3,4);ctx.globalAlpha=1}}}}
    if(stage.type==='roof'){ctx.strokeStyle='#a9c5e533';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(w*.1,h*.49);ctx.lineTo(w*.1,h*.31);ctx.lineTo(w*.32,h*.31);ctx.stroke();ctx.beginPath();ctx.moveTo(w*.77,h*.48);ctx.lineTo(w*.77,h*.25);ctx.lineTo(w*.91,h*.25);ctx.stroke()}
  }
  // stage-specific neon sign or torii marker
  if(stage.type==='neon'){
    ctx.save();ctx.translate(w*.18,h*.26);ctx.rotate(-.07);ctx.fillStyle='#13131b';ctx.fillRect(-35,-16,70,29);ctx.strokeStyle=glow;ctx.shadowColor=glow;ctx.shadowBlur=12;ctx.strokeRect(-35,-16,70,29);ctx.fillStyle='#fff0d6';ctx.font=`bold ${Math.max(9,w*.018)}px monospace`;ctx.textAlign='center';ctx.fillText('OPEN 24H',0,4);ctx.restore();
  }
  if(stage.type==='roof'){ctx.fillStyle='#11151c';ctx.fillRect(0,h*.56,w,h*.07);ctx.strokeStyle='#697482';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,h*.56);ctx.lineTo(w,h*.56);ctx.stroke();for(let x=0;x<w;x+=26){ctx.beginPath();ctx.moveTo(x,h*.56);ctx.lineTo(x,h*.48);ctx.stroke()}}
  if(stage.type==='dojo'){ctx.fillStyle='#1b201f';ctx.fillRect(0,h*.54,w,h*.055);ctx.strokeStyle='#867859';ctx.lineWidth=2;ctx.strokeRect(w*.35,h*.39,w*.3,h*.17);ctx.fillStyle='#ccb77d';ctx.font=`${Math.max(8,w*.014)}px serif`;ctx.textAlign='center';ctx.fillText('道',w*.5,h*.48)}
  // ground plane
  let floor=ctx.createLinearGradient(0,h*.63,0,h);floor.addColorStop(0,stage.type==='dojo'?'#2a342c':stage.type==='lava'?'#241719':'#15151b');floor.addColorStop(1,'#090a0d');ctx.fillStyle=floor;ctx.fillRect(0,h*.62,w,h*.38);
  ctx.strokeStyle=stage.type==='dojo'?'#d1c09018':stage.type==='lava'?'#ff7b301a':'#a7c7df18';ctx.lineWidth=1;
  for(let i=0;i<9;i++){let y=h*.64+i*i*h*.004;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
  for(let i=-5;i<=5;i++){ctx.beginPath();ctx.moveTo(w*.5+i*w*.045,h*.62);ctx.lineTo(w*.5+i*w*.19,h);ctx.stroke()}
  ctx.fillStyle=glow;ctx.globalAlpha=.4;ctx.fillRect(0,h*.62,w,2);ctx.globalAlpha=1;
