  }
}

function drawPortrait(canvas,fighter,color,opponent=false){const box=fitCanvas(canvas);if(!box)return;const {ctx,w,h}=box;ctx.clearRect(0,0,w,h);const glow=ctx.createRadialGradient(w*.5,h*.45,2,w*.5,h*.5,h*.52);glow.addColorStop(0,(color||fighter.color)+'33');glow.addColorStop(1,'#11121700');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);drawFighter(ctx,w*.51,h*.91,Math.min(w/130,h/183)*.96,fighter,color,opponent?-1:1,'idle',performance.now()/1000)}
function renderFighterChoices(){playerSelect.innerHTML='';roster.forEach((f,i)=>{const b=document.createElement('button');b.className='fighter-option'+(state.player===i?' selected':'');b.style.setProperty('--option-color',f.color);b.innerHTML=`<span class="option-mark">${f.icon}</span><span><strong>${f.name}</strong><small>${f.style}</small></span>`;b.onclick=()=>{state.player=i;if(state.opponent===i)state.opponent=(i+1)%roster.length;renderBuilder()};playerSelect.append(b)})}
function renderStats(){const f=roster[state.player],names=['POWER','GUARD','SPEED'];$('#fighterStats').innerHTML=names.map((n,i)=>`<div class="stat-row"><span>${n}</span><div class="stat-track"><div class="stat-fill" style="width:${f.stats[i]*20}%;--option-color:${state.playerColor}"></div></div><span class="stat-value">0${f.stats[i]}</span></div>`).join('')}
function renderStageDots(){stageDots.innerHTML=stages.map((s,i)=>`<button class="stage-dot ${i===state.stage?'active':''}" aria-label="Select ${s.name}" data-stage="${i}"></button>`).join('');$$('.stage-dot').forEach(b=>b.onclick=()=>setStage(+b.dataset.stage))}
