 const f=roster[state.player],r=roster[state.opponent],s=stages[state.stage];
 renderFighterChoices();$('#fighterName').textContent=state.playerName||f.name;$('#callsign').value=state.playerName;$('#fighterStyle').textContent=f.style;
 $('#swatches').innerHTML=palettes.map(c=>`<button class="swatch ${c===state.playerColor?'selected':''}" style="background:${c}" data-color="${c}" aria-label="Select color ${c}"></button>`).join('');$$('.swatch').forEach(b=>b.onclick=()=>{state.playerColor=b.dataset.color;renderBuilder()});renderStats();
 $('#opponentName').textContent=r.name;$('#opponentStyle').textContent=r.style;$('#aiLevel').value=state.ai;$('#aiLabel').textContent=aiNames[state.ai-1];$('#aiLevel').style.background=`linear-gradient(90deg,var(--orange) 0%,var(--orange) ${(state.ai-1)*25}%,#393a40 ${(state.ai-1)*25}%)`;
 $('#stageName').innerHTML=s.name.replace(' ','<br/>');$('#stageTheme').textContent=s.theme;$('#stageDesc').textContent=s.desc;$('#stageBottomName').textContent=s.name;$('#stageNumber').textContent=`STAGE 0${state.stage+1} / 04`;$('#stageDots').setAttribute('aria-label',`Stage ${state.stage+1} of 4`);$('#summaryPlayer').textContent=state.playerName||f.name;$('#summaryOpponent').textContent=r.name;$('#summaryRounds').textContent=`BEST OF ${state.rounds*2-1}`;$('#summaryTime').textContent=state.seconds===99?'∞ TIME':`${state.seconds} SEC`;$('#summaryHazards').textContent=state.hazards?'HAZARDS ON':'CLEAN FIGHT';
 $('#meterToggle').classList.toggle('is-on',state.meter);$('#meterToggle').setAttribute('aria-pressed',String(state.meter));$('#meterToggle b').textContent=state.meter?'ENABLED':'DISABLED';$('#hazardToggle').classList.toggle('is-on',state.hazards);$('#hazardToggle').setAttribute('aria-pressed',String(state.hazards));$('#hazardToggle b').textContent=state.hazards?'ENABLED':'DISABLED';
 drawPortrait($('#portraitCanvas'),f,state.playerColor);drawPortrait($('#opponentCanvas'),r,r.color,true);renderStageDots();drawPreview();
}
function setStage(i){state.stage=(i+stages.length)%stages.length;renderBuilder()}
