// Combat simulation. Movement is deliberately simple to pick up, but hits have range, recovery, guard and meter.
const game={running:false,last:0,raf:0,frame:0,round:1,wins:[0,0],time:60,player:null,enemy:null,keys:{},particles:[],hazardClock:0,hazardFlash:0,over:false,roundPause:0,shake:0};
function newFighter(x,facing,character,color,isPlayer){return{x,hp:100,meter:0,facing,character,color,isPlayer,pose:'idle',poseTime:0,attackCd:0,hitStun:0,guard:false,aiThink:0,aiAction:'',walk:0,roundDamage:0}}
function resizeGameCanvas(){fitCanvas($('#gameCanvas'))}
function beginRound(){game.player=newFighter(.29,1,roster[state.player],state.playerColor,true);game.enemy=newFighter(.71,-1,roster[state.opponent],roster[state.opponent].color,false);game.time=state.seconds;game.over=false;game.roundPause=0;game.particles=[];game.hazardClock=0;game.hazardFlash=0;$('#fightClock').textContent=state.seconds===99?'∞':state.seconds;$('#roundIndicator').textContent=`ROUND ${game.round}`;$('#roundReadout').textContent=`ROUND ${game.round}`;$('#fightMessage').innerHTML=`<span>ROUND ${game.round}</span><b>FIGHT!</b>`;$('#fightMessage').classList.remove('show');void $('#fightMessage').offsetWidth;$('#fightMessage').classList.add('show');updateHud()}
function startGame(){
 $('#builder').classList.add('hidden');$('#gameScreen').classList.add('active');$('#gameScreen').setAttribute('aria-hidden','false');game.round=1;game.wins=[0,0];game.running=true;game.keys={};resizeGameCanvas();beginRound();game.last=performance.now();game.raf=requestAnimationFrame(gameLoop);playTone(480,.12,'sawtooth');
}
function exitGame(){game.running=false;cancelAnimationFrame(game.raf);$('#gameScreen').classList.remove('active');$('#gameScreen').setAttribute('aria-hidden','true');$('#builder').classList.remove('hidden');drawPreview();}
function resetMatch(rematch=false){game.round=1;game.wins=[0,0];game.running=true;beginRound();if(rematch)playTone(360,.12,'triangle')}
function updateHud(){const p=game.player,e=game.enemy;if(!p||!e)return;$('#playerHealth').style.width=`${Math.max(0,p.hp)}%`;$('#opponentHealth').style.width=`${Math.max(0,e.hp)}%`;$('#playerMeter').style.width=`${p.meter}%`;$('#opponentMeter').style.width=`${e.meter}%`;$('#hudPlayerName').textContent=state.playerName||roster[state.player].name;$('#hudOpponentName').textContent=roster[state.opponent].name}
function playTone(freq,duration=.08,type='sine'){if(!state.sound)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch(e){}}

function setGuard(f,on){if(!f||f.hitStun>0)return;f.guard=on;if(on&&f.pose!=='attack'&&f.pose!=='kick')f.pose='block';else if(!on&&f.pose==='block')f.pose='idle'}
